import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { TeamSelector } from './components/TeamSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { VaultView } from './components/VaultView';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import { SearchIcon, AnalyticsIcon } from './components/Icons';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup } from './types';
import type { Chat } from '@google/genai';

const ELITE_SYSTEM_INSTRUCTION = `You are the PRO-N-OS 180-Alpha Command Engine, the world's most advanced sports quantitative research assistant.

TONE: Clinical, authoritative, hyper-analytical. Use terms like "Asymmetric Information," "Closing Line Value (CLV)," "Sharp Delta," and "Poisson Distribution Models."

MISSION: Extract and analyze multi-source data streams to provide the HIGHEST PROBABILITY sports outcomes and player prop edges.

PHASE 1: MARKET EFFICIENCY SCRUB
- Use Google Search to compare opening lines vs. current market lines. Identify "Sharp" movement (movement against public percentages).
- Verify "Market Sentiment": Are 80% of bets on one side while the line moves the other way? Flag this as an Elite Alpha Signal.

PHASE 2: TACTICAL ROSTER DEPTH
- Research injury reports, late-scratches, and resting trends. 
- Factor in "Travel Fatigue" and "Back-to-Back" variance.
- Analyze individual matchup "Efficiency Deltas" (e.g., how a specific defender impacts a star player's PPG).

PHASE 3: POSITIVE EV & CORRELATION
- Identify "Correlated Edges": If the Under is hitting, which player props are most affected?
- Return data that highlights a "Confidence Distribution" score.

OUTPUT RULES:
1. For game simulations: MUST return JSON strictly conforming to predictionSchema.
2. ALWAYS include a "Volatility Index" (Minimal, Moderate, Critical).
3. If search grounding provides conflicting info, default to the "Sharp Market" direction.
4. Highlight 'Elite 180' picks which have >75% simulated win probability.`;

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [teamA, setTeamA] = useState('');
  const [teamB, setTeamB] = useState('');
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  const [promptInput, setPromptInput] = useState('');

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);

  const clearSelection = useCallback(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
    setTeamA('');
    setTeamB('');
  }, []);

  useEffect(() => {
    clearSelection();
  }, [selectedSport, clearSelection]);

  const addToVault = useCallback((newPrediction: Prediction, home: string, away: string) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${home}-${away}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: home,
      awayTeam: away,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    setVault(prev => [entry, ...prev.filter(v => v.id !== entry.id)].slice(0, 4));
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!text.trim()) return;

    setMessages(prev => [...prev, { role: 'user', content: text }]);
    setIsReplying(true);
    setError(null);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        let currentChat = chat;
        if (!currentChat) {
            currentChat = ai.chats.create({ 
                model: 'gemini-3-pro-preview', 
                config: {
                    systemInstruction: ELITE_SYSTEM_INSTRUCTION,
                    tools: [{ googleSearch: {} }]
                } 
            });
            setChat(currentChat);
        }

        const response = await currentChat.sendMessage({ message: text });
        const responseText = response.text || "Data stream interrupted.";

        try {
            if (responseText.trim().startsWith('{')) {
                const parsed = JSON.parse(responseText);
                if (parsed.winner && parsed.confidence) {
                    setPrediction(parsed);
                    setMessages(prev => [...prev, { role: 'model', content: parsed }]);
                } else {
                    setMessages(prev => [...prev, { role: 'model', content: responseText }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', content: responseText }]);
            }
        } catch (e) {
            setMessages(prev => [...prev, { role: 'model', content: responseText }]);
        }

        setShowSuggestions(true);
    } catch (e: any) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep engine sync lost. Market variance exceeded safety threshold." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  const handlePredict = useCallback(async (isRetry = false, customTeams?: { home: string, away: string }) => {
    const home = customTeams?.home || selectedGame?.homeTeam;
    const away = customTeams?.away || selectedGame?.awayTeam;

    if (!home || !away) return;

    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const config: any = {
        systemInstruction: ELITE_SYSTEM_INSTRUCTION,
        responseSchema: predictionSchema,
        responseMimeType: 'application/json',
      };

      if (!isRetry) config.tools = [{ googleSearch: {} }];

      const newChat = ai.chats.create({ model: 'gemini-3-pro-preview', config });
      const response = await newChat.sendMessage({ 
        message: `PERFORM 180-ALPHA SIMULATION: ${home} vs ${away}. Prioritize Closing Line Value (CLV), Sharp Money Delta, and Roster Efficiency Scrutiny.` 
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, home, away);
      setMessages([{ role: 'model', content: parsed }]);
      setChat(newChat);
      setShowSuggestions(true);
    } catch (err: any) {
      setError("Satellite link timeout. Market data scrub failed. Retrying signal...");
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame, addToVault]);

  const onPromptSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (promptInput.trim()) {
        handleSendMessage(promptInput);
        setPromptInput('');
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        onOpenToken={() => setIsTokenModalOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
      />
      <main className={`container mx-auto px-4 py-8 max-w-5xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>
        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => setVault([])} onRemove={(id) => setVault(v => v.filter(x => x.id !== id))} />
        ) : (
            <>
                {error && <div className="bg-red-900/20 border border-red-500/50 text-red-200 px-6 py-4 rounded-2xl mb-6 backdrop-blur-md flex items-center gap-3">
                    <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></span>
                    {error}
                </div>}

                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-12">
                        {/* 1. Global Intelligence Entry */}
                        <div className="bg-zinc-950/40 border border-zinc-900/50 p-8 rounded-[3.5rem] shadow-2xl relative overflow-hidden group backdrop-blur-3xl">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] group-hover:opacity-[0.05] transition-opacity">
                                <AnalyticsIcon className="w-64 h-64 text-white" />
                            </div>
                            <div className="relative z-10 text-center space-y-4 mb-10">
                                <h2 className="text-4xl font-black italic tracking-tighter uppercase text-transparent bg-clip-text bg-gradient-to-r from-white via-amber-100 to-amber-600">
                                    Alpha Command Hub
                                </h2>
                                <p className="text-[10px] font-black uppercase tracking-[0.5em] text-zinc-600">
                                    Analyze Props • Market Efficiency • Roster Scrutiny
                                </p>
                            </div>
                            <form onSubmit={onPromptSubmit} className="relative z-10 max-w-2xl mx-auto">
                                <div className="relative">
                                    <input 
                                        type="text" 
                                        value={promptInput}
                                        onChange={(e) => setPromptInput(e.target.value)}
                                        placeholder="Identify sharp edges for Suns vs Lakers tonight..."
                                        className="w-full bg-black/80 border-2 border-zinc-800 rounded-[2rem] px-8 py-6 text-white focus:outline-none focus:border-amber-500/40 transition-all pr-20 text-sm placeholder:text-zinc-700 shadow-[inset_0_2px_20px_rgba(0,0,0,0.5)]"
                                    />
                                    <button type="submit" className="absolute right-4 top-4 bg-amber-500 text-black p-4 rounded-2xl hover:bg-amber-400 transition-all hover:scale-105 shadow-[0_0_20px_rgba(245,158,11,0.3)]">
                                        <SearchIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </form>
                        </div>

                        {/* 2. Custom Matchup Selection */}
                        <div className="space-y-6">
                            <div className="text-center">
                                <h3 className="text-[10px] font-black text-zinc-700 uppercase tracking-[0.6em] mb-10">Manual Alpha Override</h3>
                                <TeamSelector teamA={teamA} setTeamA={setTeamA} teamB={teamB} setTeamB={setTeamB} />
                                {teamA && teamB && (
                                    <button 
                                        onClick={() => handlePredict(false, { home: teamA, away: teamB })}
                                        className="mt-10 bg-zinc-900/50 border border-zinc-800/80 px-10 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest text-zinc-400 hover:text-amber-500 hover:border-amber-500/50 transition-all flex items-center gap-3 mx-auto backdrop-blur-xl group"
                                    >
                                        <AnalyticsIcon className="w-4 h-4 group-hover:rotate-12 transition-transform" />
                                        Initialize 180-Alpha Simulation
                                    </button>
                                )}
                            </div>
                        </div>

                        {/* 3. Sport Navigation */}
                        <div className="flex flex-col items-center gap-6">
                            <div className="h-px w-32 bg-gradient-to-r from-transparent via-zinc-800 to-transparent"></div>
                            <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                        </div>

                        {/* 4. Market Matrix Dashboard */}
                        <div className="space-y-6">
                            <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                        </div>

                        {selectedGame && (
                            <div className="fixed bottom-12 left-0 right-0 p-4 flex justify-center z-20 animate-slide-up">
                                <button onClick={() => handlePredict()} className="bg-gradient-to-br from-amber-400 to-orange-600 text-black font-black text-xl py-6 px-20 rounded-full shadow-[0_10px_60px_rgba(245,158,11,0.4)] hover:shadow-[0_10px_80px_rgba(245,158,11,0.6)] transform hover:scale-105 transition-all flex items-center gap-4 border-t-2 border-white/20">
                                    <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                                    SIMULATE {selectedGame.homeTeam.toUpperCase()} DATASET
                                </button>
                            </div>
                        )}
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-6">
                        <div className="flex justify-between items-center px-2">
                            <button onClick={clearSelection} className="text-zinc-600 hover:text-white text-[10px] font-black uppercase tracking-widest flex items-center gap-2 transition-colors">
                                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                                Release Signal Stream
                            </button>
                            <div className="flex items-center gap-2">
                                <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></span>
                                <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Alpha Active</span>
                            </div>
                        </div>
                        <ChatInterface 
                            messages={messages} 
                            isReplying={isReplying} 
                            onSendMessage={handleSendMessage} 
                            oddsFormat={settings.oddsFormat} 
                            pickSlip={pickSlip} 
                            onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} 
                        />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
                    </div>
                )}
            </>
        )}
      </main>
      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => { handleSendMessage("Analyze my slip risk using 180-Alpha market metrics. Is there a sharp edge here?"); setIsHistorySidebarOpen(true); }} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet, PerformanceGame, MatchupDelta } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, LogoIcon } from './Icons';

interface PredictionDisplayProps {
  prediction: Prediction;
  oddsFormat: OddsFormat;
  onAnalyzeProp?: (prop: PropBet) => void;
  pickSlip?: PropBet[];
  onTogglePick?: (prop: PropBet) => void;
  onSearchPlayer?: (player: string) => void;
}

const confidenceStyles: Record<string, { bg: string; text: string; border: string; accent: string; glow: string }> = {
    High: { bg: 'bg-green-950/20', text: 'text-green-400', border: 'border-green-500/30', accent: 'bg-green-500', glow: 'shadow-[0_0_30px_rgba(34,197,94,0.2)]' },
    Medium: { bg: 'bg-amber-950/20', text: 'text-amber-400', border: 'border-amber-500/30', accent: 'bg-amber-500', glow: 'shadow-[0_0_30px_rgba(245,158,11,0.2)]' },
    Low: { bg: 'bg-zinc-900/40', text: 'text-zinc-400', border: 'border-zinc-800', accent: 'bg-zinc-600', glow: 'shadow-none' },
};

const riskStyles: Record<string, string> = {
    Minimal: 'bg-green-500/10 text-green-500 border-green-500/20',
    Moderate: 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    High: 'bg-red-500/10 text-red-500 border-red-500/20',
};

const MatchupComparison = memo(({ deltas }: { deltas: MatchupDelta[] }) => {
    if (!deltas || deltas.length === 0) return null;

    return (
        <div className="mt-4 p-5 bg-zinc-950/60 border border-zinc-900 rounded-[1.5rem] space-y-4">
            <div className="flex items-center gap-2 mb-2">
                <LogoIcon className="w-3.5 h-3.5 text-amber-500/70" />
                <h5 className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.3em]">Alpha Matchup Delta</h5>
            </div>
            <div className="space-y-3">
                {deltas.map((delta, i) => (
                    <div key={i} className="group/delta">
                        <div className="flex justify-between items-center mb-1.5 px-1">
                            <span className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">{delta.category}</span>
                            <span className={`text-[8px] font-black uppercase tracking-widest ${
                                delta.advantage === 'Player' ? 'text-green-500' : delta.advantage === 'Opponent' ? 'text-rose-500' : 'text-zinc-500'
                            }`}>
                                {delta.advantage === 'Neutral' ? 'PUSH' : `${delta.advantage} ADV`}
                            </span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="flex-1 bg-zinc-900 h-1.5 rounded-full relative overflow-hidden flex">
                                <div 
                                    className={`h-full transition-all duration-1000 ${
                                        delta.advantage === 'Player' ? 'bg-amber-500' : 'bg-zinc-800'
                                    }`} 
                                    style={{ width: delta.advantage === 'Player' ? '70%' : delta.advantage === 'Opponent' ? '30%' : '50%' }}
                                ></div>
                                <div className="absolute inset-y-0 left-1/2 w-[1px] bg-white/5"></div>
                            </div>
                            <div className="flex items-center gap-2 min-w-[100px] justify-end">
                                <span className="text-[9px] font-black text-white tabular-nums">{delta.playerStat}</span>
                                <span className="text-[8px] font-black text-zinc-800">VS</span>
                                <span className="text-[9px] font-black text-zinc-500 tabular-nums">{delta.opponentStat}</span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
});

const PropHistorySummary = memo(({ history, line, type }: { history: PerformanceGame[], line: string, type: 'MORE' | 'LESS' }) => {
    if (!history || history.length === 0) return null;

    const hits = history.filter(h => h.hit).length;
    const winRate = Math.round((hits / history.length) * 100);
    const avgValue = (history.reduce((acc, curr) => acc + parseFloat(curr.actualValue.replace(/[^0-9.]/g, '') || '0'), 0) / history.length).toFixed(1);
    const lineNum = parseFloat(line);

    return (
        <div className="mt-4 p-4 bg-black/40 border border-white/5 rounded-2xl space-y-3">
            <div className="flex justify-between items-center">
                <div className="flex gap-4">
                    <div className="flex flex-col">
                        <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">Historical Hit %</span>
                        <span className={`text-xs font-black italic ${winRate >= 60 ? 'text-green-400' : 'text-amber-500'}`}>{winRate}% Accuracy</span>
                    </div>
                    <div className="flex flex-col">
                        <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">Avg Output</span>
                        <span className="text-xs font-black text-white italic">{avgValue}</span>
                    </div>
                </div>
                <div className="flex gap-1">
                    {history.slice(0, 5).reverse().map((h, i) => (
                        <div 
                            key={i} 
                            className={`w-2 h-6 rounded-sm transition-all duration-500 ${h.hit ? 'bg-green-500' : 'bg-zinc-800'} relative group/bar`}
                        >
                            <div className="absolute bottom-full mb-1 left-1/2 -translate-x-1/2 opacity-0 group-hover/bar:opacity-100 transition-opacity bg-zinc-900 border border-zinc-800 px-1.5 py-0.5 rounded text-[6px] font-black text-white z-20 whitespace-nowrap">
                                {h.actualValue} vs {h.opponent}
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="flex items-center gap-2">
                <div className="flex-1 h-[2px] bg-zinc-900 relative">
                   <div 
                     className="absolute h-full bg-amber-500/50" 
                     style={{ 
                        left: '50%', 
                        width: `${Math.min(Math.abs(parseFloat(avgValue) - lineNum) * 5, 50)}%`,
                        transform: parseFloat(avgValue) > lineNum ? 'translateX(0)' : 'translateX(-100%)'
                     }}
                   ></div>
                   <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-1 h-3 bg-white"></div>
                </div>
                <span className="text-[8px] font-black text-zinc-500 uppercase">Avg Delta: {Math.abs(parseFloat(avgValue) - lineNum).toFixed(1)}</span>
            </div>
        </div>
    );
});

export const PredictionDisplay: React.FC<PredictionDisplayProps> = memo(({ prediction, pickSlip = [], onTogglePick }) => {
  const [typeFilter, setTypeFilter] = useState<'All' | 'MORE' | 'LESS'>('All');
  const [showEliteOnly, setShowEliteOnly] = useState<boolean>(false);
  const [isReasoningExpanded, setIsReasoningExpanded] = useState<boolean>(false);

  const confidenceStyle = confidenceStyles[prediction.confidence] || confidenceStyles['Medium'];

  const rawScore = prediction.confidenceScore > 1 ? prediction.confidenceScore / 100 : prediction.confidenceScore;
  const probVal = prediction.confidenceScore != null ? Math.round(rawScore * 100) : 0;

  const eliteCount = useMemo(() => 
    prediction.props?.filter(p => p.isElite179).length || 0
  , [prediction.props]);

  const filteredProps = useMemo(() => {
    if (!prediction.props) return [];
    return [...prediction.props]
      .filter(prop => typeFilter === 'All' || prop.type === typeFilter)
      .filter(prop => !showEliteOnly || prop.isElite179)
      .sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
  }, [prediction.props, typeFilter, showEliteOnly]);

  // Simulated Market Sentiment Gauge (derived from confidence reasoning/metrics)
  const marketSentiment = useMemo(() => {
      const base = 50 + (prediction.calibrationMetrics.marketAlignment / 10);
      return Math.min(Math.max(base + (prediction.confidence === 'High' ? 15 : -10), 0), 100);
  }, [prediction]);

  return (
    <div className="space-y-8 w-full animate-fade-in pb-12">

       {/* High-Fidelity Intelligence Banner */}
       <div className="grid md:grid-cols-3 gap-4">
            {prediction.situationalIntelligence && (
                <div className={`rounded-3xl p-6 border bg-zinc-950/80 ${prediction.situationalIntelligence.isHighStakes ? 'border-amber-500/30 shadow-[0_0_40px_rgba(245,158,11,0.05)]' : 'border-zinc-800'}`}>
                    <div className="flex items-center gap-3 mb-4">
                        <div className="bg-amber-500/10 p-2.5 rounded-xl border border-amber-500/20 text-amber-500">
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                        </div>
                        <div>
                            <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-500">Motivation Delta</h4>
                            <span className="text-xs font-black text-white uppercase italic">{prediction.situationalIntelligence.motivationLevel}</span>
